enum { IDLE, PRESSED } state = IDLE;

void loop() {
  switch (state) {
  case IDLE:
    if (digitalRead(2) == LOW)
      state = PRESSED;
    break;
  case PRESSED:
    digitalWrite(13, HIGH);
    delay(2000);
    digitalWrite(13, LOW);
    state = IDLE;
    break;
  }
}

